{
  "title": "修复生命支持系统",
  "scene": "你所在的宇宙飞船在一次意外中受损，你现在位于受损最严重的前舱。生命支持系统受损，飞船内的氧气即将耗尽。你发现一个控制面板上显示着三个故障代码：A、B和C。你需要选择一个故障代码进行修复。",
  "goal": "找到正确的故障代码并修复它，以恢复生命支持系统。",
  "choices": [
    {
      "id": "A",
      "text": "选择A代码",
      "outcome": "检查发现A代码对应的区域有轻微的电路过热，但没有其他损坏。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "选择B代码",
      "outcome": "检查发现B代码对应的区域存在严重的电路短路，必须先进行隔离处理，然后才能修复。",
      "result": "fail",
      "next": "bad_end"
    },
    {
      "id": "C",
      "text": "选择C代码",
      "outcome": "检查发现C代码对应的区域只是小范围的电路中断，很容易修复。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
